import javax.tools.ToolProvider;import java.nio.file.*;public class Compile{public static void main(String[] a)throws Exception{String[] files;try(var s=Files.walk(Path.of(a[0]))){files=s.filter(p->p.toString().endsWith(".java")).map(Object::toString).toArray(String[]::new);}int result=ToolProvider.getSystemJavaCompiler().run(null,null,null,files);if(result!=0)throw new RuntimeException("javac "+result);}}